/* Generated from spatial-crisp.astrale-theme.json. Consumer-owned after installation. */
:root,
[data-ui-preset='spatial-crisp'],
[data-ui-theme='spatial-crisp'] {
  color-scheme: light;
  --ui-background: oklch(0.952 0.003 258);
  --ui-foreground: oklch(0.18 0.013 258);
  --ui-card: oklch(0.995 0.0015 258);
  --ui-card-foreground: oklch(0.18 0.013 258);
