  --ui-radius-panel: 0.625rem;
  --ui-radius-action: initial;
  --ui-control-height: 2.25rem;
  --ui-control-height-sm: 2rem;
  --ui-control-height-lg: 2.5rem;
  --ui-control-padding: 0.75rem;
  --ui-panel-spacing: 1rem;
  --ui-font-body: 'Hanken Grotesk', 'Hanken Grotesk Variable', 'Manrope', ui-sans-serif, system-ui, sans-serif;
  --ui-font-heading: 'Hanken Grotesk', 'Hanken Grotesk Variable', 'Manrope', ui-sans-serif, system-ui, sans-serif;
  --ui-font-mono: 'SFMono-Regular', 'Cascadia Code', ui-monospace, monospace;
  --ui-tracking-body: -0.005em;
  --ui-tracking-heading: -0.02em;
  --ui-leading-body: 1.45;
  --ui-leading-heading: 1.2;
  --ui-weight-body: 470;
  --ui-weight-heading: 650;
  --ui-weight-label: 580;
  --ui-shadow-control: 0 1px 1px oklch(0.22 0.025 258 / 0.07);
  --ui-shadow-panel:
    0 1px 2px oklch(0.22 0.025 258 / 0.07), 0 3px 10px -4px oklch(0.22 0.025 258 / 0.1);
  --ui-shadow-overlay:
    0 2px 4px oklch(0.22 0.025 258 / 0.08), 0 12px 28px -10px oklch(0.22 0.025 258 / 0.22);
  --ui-backdrop: oklch(0.2 0.01 258 / 0.3);
  --ui-motion-fast: 120ms;
  --ui-motion-standard: 180ms;
}

